'use client'
import Link from "next/link"
import { portfolio } from "@/data/portfolio"
import { ArrowRight, Clock, Tag } from "lucide-react"

function findPost(slug: string) {
  return portfolio.blogPosts?.find(
    (p: any) => p.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") === slug
  )
}

export function BlogPostClient({ slug }: { slug: string }) {
  const post = findPost(slug)

  if (!post) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center">
        <div className="text-center">
          <p className="text-6xl font-bold text-gray-200 mb-4">404</p>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Post not found</h1>
          <p className="text-sm text-gray-500 mb-4">This post may have been moved or is no longer available.</p>
          <Link href="/" className="text-sm text-gray-500 hover:text-gray-900 inline-block">← Back to Home</Link>
        </div>
      </div>
    )
  }

  return (
    <article className="min-h-screen bg-white pt-24 pb-16">
      <div className="max-w-3xl mx-auto px-6 md:px-12">
        <Link href="/#blog" className="text-sm text-gray-400 hover:text-gray-900 transition-colors inline-block mb-8">
          ← Back to Blog
        </Link>

        <header className="mb-12">
          <div className="flex items-center gap-3 mb-4">
            {post.tag && (
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-blue-50 text-blue-600">
                <Tag className="w-3 h-3" />
                {post.tag}
              </span>
            )}
            {post.readTime && (
              <span className="inline-flex items-center gap-1.5 text-xs text-gray-400">
                <Clock className="w-3 h-3" />
                {post.readTime}
              </span>
            )}
          </div>
          <h1 className="text-3xl md:text-4xl font-bold text-gray-900 leading-tight">{post.title}</h1>
          <p className="text-lg text-gray-500 mt-4 leading-relaxed">{post.description}</p>
          <div className="flex items-center gap-3 mt-6 pt-6 border-t border-gray-100">
            <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center">
              <span className="text-sm font-semibold text-gray-600">HC</span>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-900">Hmimi Chioukh</p>
              <p className="text-xs text-gray-400">AI Product Designer</p>
            </div>
          </div>
        </header>

        <div className="bg-gray-50 rounded-2xl p-8 md:p-12 text-center mb-12">
          <p className="text-gray-500 mb-6 leading-relaxed">
            This article was originally published on Medium and explores practical design workflows, UX patterns, and product thinking.
          </p>
          <a
            href={post.url}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 bg-gray-900 text-white rounded-full px-6 py-3 text-sm font-medium hover:bg-gray-800 transition-colors"
          >
            Read Full Article on Medium
            <ArrowRight className="h-4 w-4" />
          </a>
        </div>

        <div className="border-t border-gray-100 pt-8">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">About the Author</h2>
          <div className="flex items-start gap-4">
            <div className="w-12 h-12 rounded-full bg-gray-200 flex items-center justify-center shrink-0">
              <span className="text-sm font-semibold text-gray-600">HC</span>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-900">Hmimi Chioukh</p>
              <p className="text-sm text-gray-500 mt-1 leading-relaxed">
                AI Product Designer building scalable SaaS platforms. Focused on clarity, speed, and operational UX.
              </p>
              <div className="flex gap-4 mt-3">
                <a href="https://linkedin.com/in/hmimi-chioukh" target="_blank" rel="noopener noreferrer" className="text-xs text-gray-400 hover:text-gray-900">LinkedIn</a>
                <a href="https://dribbble.com/chioukh_hmimi" target="_blank" rel="noopener noreferrer" className="text-xs text-gray-400 hover:text-gray-900">Dribbble</a>
                <a href="https://github.com/Chioukhhmimi" target="_blank" rel="noopener noreferrer" className="text-xs text-gray-400 hover:text-gray-900">GitHub</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </article>
  )
}
